/// <summary>
/// Parm method for the rebate transaction type
/// </summary>
/// <param name = "_metRebateTransactionType"><c>TAMRebateTransactionType</c></param>
/// <returns><c>TAMRebateTransactionType</c></returns>
public TAMRebateTransactionType metParmRebateTransactionType(TAMRebateTransactionType _metRebateTransactionType = metRebateTransactionType)
{
    metRebateTransactionType = _metRebateTransactionType;
    return metRebateTransactionType;
}
